import heapq
class EventManager:
    def __init__(self, events):
        self.pri = {}
        self.heap = []
        for eid, p in events:
            self.pri[eid] = p
            heapq.heappush(self.heap, (-p, eid))
    def updatePriority(self, eventId, newPriority):
        self.pri[eventId] = newPriority
        heapq.heappush(self.heap, (-newPriority, eventId))
    def pollHighest(self):
        while self.heap:
            negp, eid = heapq.heappop(self.heap)
            if eid in self.pri and self.pri[eid] == -negp:
                del self.pri[eid]
                return eid
        return -1

