class EventManager {
    unordered_map<int,int> pri;
    priority_queue<pair<int,int>> pq;
public:
    EventManager(vector<vector<int>>& events) {
        for (auto& e : events) {
            pri[e[0]] = e[1];
            pq.push({e[1], -e[0]});
        }
    }
    void updatePriority(int eventId, int newPriority) {
        pri[eventId] = newPriority;
        pq.push({newPriority, -eventId});
    }
    int pollHighest() {
        while (!pq.empty()) {
            auto [p, negeid] = pq.top(); pq.pop();
            int eid = -negeid;
            auto it = pri.find(eid);
            if (it != pri.end() && it->second == p) {
                pri.erase(it);
                return eid;
            }
        }
        return -1;
    }
};

