class EventManager {
    constructor(events) {
        this.pri = new Map();
        this.heap = [];
        for (const [eid, p] of events) {
            this.pri.set(eid, p);
            this.push([-p, eid]);
        }
    }
    push(item) {
        this.heap.push(item);
        let i = this.heap.length - 1;
        while (i > 0) {
            const par = (i - 1) >> 1;
            if (this.heap[par] <= this.heap[i]) break;
            [this.heap[par], this.heap[i]] = [this.heap[i], this.heap[par]];
            i = par;
        }
    }
    pop() {
        const top = this.heap[0], last = this.heap.pop();
        if (this.heap.length) {
            this.heap[0] = last;
            let i = 0;
            for (;;) {
                let l = 2*i+1, r = l+1, m = i;
                if (l < this.heap.length && this.heap[l] < this.heap[m]) m = l;
                if (r < this.heap.length && this.heap[r] < this.heap[m]) m = r;
                if (m === i) break;
                [this.heap[m], this.heap[i]] = [this.heap[i], this.heap[m]]; i = m;
            }
        }
        return top;
    }
    updatePriority(eventId, newPriority) {
        this.pri.set(eventId, newPriority);
        this.push([-newPriority, eventId]);
    }
    pollHighest() {
        while (this.heap.length) {
            const [negp, eid] = this.pop();
            if (this.pri.has(eid) && this.pri.get(eid) === -negp) {
                this.pri.delete(eid);
                return eid;
            }
        }
        return -1;
    }
}

