import bisect
class EventManager:
    def __init__(self, events):
        self.keys = []
        self.pri = {}
        for eid, p in events:
            self.pri[eid] = p
            bisect.insort(self.keys, (-p, eid))
    def updatePriority(self, eventId, newPriority):
        old = (-self.pri[eventId], eventId)
        i = bisect.bisect_left(self.keys, old)
        del self.keys[i]
        self.pri[eventId] = newPriority
        bisect.insort(self.keys, (-newPriority, eventId))
    def pollHighest(self):
        if not self.keys:
            return -1
        negp, eid = self.keys.pop(0)
        del self.pri[eid]
        return eid

