class EventManager {
    private TreeSet<long[]> s = new TreeSet<>((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
    private Map<Integer, Long> pri = new HashMap<>();
    public EventManager(int[][] events) {
        for (int[] e : events) {
            pri.put(e[0], (long) e[1]);
            s.add(new long[]{-e[1], e[0]});
        }
    }
    public void updatePriority(int eventId, int newPriority) {
        s.remove(new long[]{-pri.get(eventId).intValue(), eventId});
        pri.put(eventId, (long) newPriority);
        s.add(new long[]{-newPriority, eventId});
    }
    public int pollHighest() {
        if (s.isEmpty()) return -1;
        long[] first = s.pollFirst();
        pri.remove((int) first[1]);
        return (int) first[1];
    }
}

